    if (obj.newJid) pbf.writeStringField(3, obj.newJid);
    if (obj.oldJid) pbf.writeStringField(4, obj.oldJid);
    if (obj.lastMsgTimestamp) pbf.writeVarintField(5, obj.lastMsgTimestamp);
