    if (obj.parentGroupId) pbf.writeStringField(37, obj.parentGroupId);
    if (obj.isDefaultSubgroup) pbf.writeBooleanField(36, obj.isDefaultSubgroup);
    if (obj.displayName) pbf.writeStringField(38, obj.displayName);
